local function route_heading(npc,p)
  if p[4] ~= -1 then return p[4] end
  local dx,dy = p[1]-npc:GetX(),p[2]-npc:GetY()
  if dx == 0 and dy == 0 then return npc:GetHeading() end
  return (math.atan2(dx,dy)*512/(2*math.pi)+512)%512
end

local function signal_army(signal)
  for npc in eq.get_entity_list():GetNPCEntries() do
    if army_ids[npc:GetNPCTypeID()] then npc:Signal(signal) end
  end
end
