function event_timer(e)
  if e.timer ~= "advance" or state ~= "paused" then return end
  eq.stop_timer("advance")
  if e.self:IsEngaged() then eq.set_timer("advance",1000); return end
  if route == "march" and leg == #march then route = "charge"; leg = 0 end
  leg = leg + 1
  if route == "charge" and leg > #charge then state = "ended"; eq.depop(); return end
  walk(e)
end
function event_trade(e)
